/**
 * The `Error` enum of this pallet.
 **/
export type PalletXcmError =
  /**
   * The desired destination was unreachable, generally because there is a no way of routing
   * to it.
   **/
  | { name: 'Unreachable' }
  /**
   * There was some other issue (i.e. not to do with routing) in sending the message.
   * Perhaps a lack of space for buffering the message.
   **/
  | { name: 'SendFailure' }
  /**
   * The message execution fails the filter.
   **/
  | { name: 'Filtered' }
  /**
   * The message's weight could not be determined.
   **/
  | { name: 'UnweighableMessage' }
  /**
   * The destination `Location` provided cannot be inverted.
   **/
  | { name: 'DestinationNotInvertible' }
  /**
   * The assets to be sent are empty.
   **/
  | { name: 'Empty' }
  /**
   * Could not re-anchor the assets to declare the fees for the destination chain.
   **/
  | { name: 'CannotReanchor' }
  /**
   * Too many assets have been attempted for transfer.
   **/
  | { name: 'TooManyAssets' }
  /**
   * Origin is invalid for sending.
   **/
  | { name: 'InvalidOrigin' }
  /**
   * The version of the `Versioned` value used is not able to be interpreted.
   **/
  | { name: 'BadVersion' }
  /**
   * The given location could not be used (e.g. because it cannot be expressed in the
   * desired version of XCM).
   **/
  | { name: 'BadLocation' }
  /**
   * The referenced subscription could not be found.
   **/
  | { name: 'NoSubscription' }
  /**
   * The location is invalid since it already has a subscription from us.
   **/
  | { name: 'AlreadySubscribed' }
  /**
   * Could not check-out the assets for teleportation to the destination chain.
   **/
  | { name: 'CannotCheckOutTeleport' }
  /**
   * The owner does not own (all) of the asset that they wish to do the operation on.
   **/
  | { name: 'LowBalance' }
  /**
   * The asset owner has too many locks on the asset.
   **/
  | { name: 'TooManyLocks' }
  /**
   * The given account is not an identifiable sovereign account for any location.
   **/
  | { name: 'AccountNotSovereign' }
  /**
   * The operation required fees to be paid which the initiator could not meet.
   **/
  | { name: 'FeesNotMet' }
  /**
   * A remote lock with the corresponding data could not be found.
   **/
  | { name: 'LockNotFound' }
  /**
   * The unlock operation cannot succeed because there are still consumers of the lock.
   **/
  | { name: 'InUse' }
  /**
   * Invalid asset, reserve chain could not be determined for it.
   **/
  | { name: 'InvalidAssetUnknownReserve' }
  /**
   * Invalid asset, do not support remote asset reserves with different fees reserves.
   **/
  | { name: 'InvalidAssetUnsupportedReserve' }
  /**
   * Too many assets with different reserve locations have been attempted for transfer.
   **/
  | { name: 'TooManyReserves' }
  /**
   * Local XCM execution incomplete.
   **/
  | { name: 'LocalExecutionIncomplete' }
  /**
   * Too many locations authorized to alias origin.
   **/
  | { name: 'TooManyAuthorizedAliases' }
  /**
   * Expiry block number is in the past.
   **/
  | { name: 'ExpiresInPast' }
  /**
   * The alias to remove authorization for was not found.
   **/
  | { name: 'AliasNotFound' }
  /**
   * Local XCM execution incomplete with the actual XCM error and the index of the
   * instruction that caused the error.
   **/
  | { name: 'LocalExecutionIncompleteWithError'; data: { index: number; error: PalletXcmErrorsExecutionError } };

export type PalletXcmErrorsExecutionError =
  | 'Overflow'
  | 'Unimplemented'
  | 'UntrustedReserveLocation'
  | 'UntrustedTeleportLocation'
  | 'LocationFull'
  | 'LocationNotInvertible'
  | 'BadOrigin'
  | 'InvalidLocation'
  | 'AssetNotFound'
  | 'FailedToTransactAsset'
  | 'NotWithdrawable'
  | 'LocationCannotHold'
  | 'ExceedsMaxMessageSize'
  | 'DestinationUnsupported'
  | 'Transport'
  | 'Unroutable'
  | 'UnknownClaim'
  | 'FailedToDecode'
  | 'MaxWeightInvalid'
  | 'NotHoldingFees'
  | 'TooExpensive'
  | 'Trap'
  | 'ExpectationFalse'
  | 'PalletNotFound'
  | 'NameMismatch'
  | 'VersionIncompatible'
  | 'HoldingWouldOverflow'
  | 'ExportError'
  | 'ReanchorFailed'
  | 'NoDeal'
  | 'FeesNotMet'
  | 'LockError'
  | 'NoPermission'
  | 'Unanchored'
  | 'NotDepositable'
  | 'TooManyAssets'
  | 'UnhandledXcmVersion'
  | 'WeightLimitReached'
  | 'Barrier'
